function initLinks() {
 var shopLinks = document.querySelectorAll('.custom-link-test.shop');
 var arrMetricsLinkIDs = [];

 shopLinks.forEach(function(link, index) {
 // replace placeholder with actual hash search term
 link.href = link.href.replace('REPLACE-THIS-TERM', encodeURIComponent(location.hash));

 // change existing link ID for learn link to have index
 var firstLink = link.parentElement.querySelector('a');
 var firstLinkMetricsID = firstLink.getAttribute('data-metrics-link-id');
 arrMetricsLinkIDs.push(firstLinkMetricsID);
 firstLink.setAttribute('data-metrics-link-id', firstLinkMetricsID + '\_learn' + (index+1));

 link.addEventListener('click', function(e) {
 var analyticsObj = {event: 'e\_linkClick', linkPlacement: 'search2022', linkID: firstLinkMetricsID + '\_shop' + (index+1)};
 window.dataLayer.push(analyticsObj);
 });
 })

 var supportLinks = document.querySelectorAll('.custom-link-test.support');
 supportLinks.forEach(function(link, index) {
 // replace placeholder with actual hash search term
 link.href = link.href.replace('REPLACE-THIS-TERM', encodeURIComponent(location.hash));
 link.addEventListener('click', function(e) {
 var analyticsObj = {event: 'e\_linkClick', linkPlacement: 'search2022', linkID: arrMetricsLinkIDs[index] + '\_support' + (index+1)};
 window.dataLayer.push(analyticsObj);
 });
 })
}

var intervalID = window.setInterval(function() {
 if (document.querySelectorAll('.custom-link-test.shop').length &&
 document.querySelectorAll('.custom-link-test.support').length) {
 window.clearInterval(intervalID);
 initLinks();
 }
}, 100);
